-- Decision Lab v4 persistence. No public policies; service ingestion remains token-gated.
create table if not exists decision_thesis_events(id bigint generated by default as identity primary key,origin_node text not null,origin_id text not null,event_time timestamptz not null,state text not null,payload jsonb not null,unique(origin_node,origin_id));
create table if not exists decision_forward_ledger(id bigint generated by default as identity primary key,origin_node text not null,origin_id text not null,created_at timestamptz not null,symbol text not null,horizon text not null,target_date timestamptz not null,model_version text not null,prediction_hash text not null,payload jsonb not null,outcome jsonb,evaluated_at timestamptz,unique(origin_node,origin_id),unique(prediction_hash));
create table if not exists decision_research_ledger(id bigint generated by default as identity primary key,origin_node text not null,origin_id text not null,created_at timestamptz not null,question text not null,payload jsonb not null,later_correctness double precision,unique(origin_node,origin_id));
create table if not exists decision_committee_votes(id bigint generated by default as identity primary key,origin_node text not null,origin_id text not null,created_at timestamptz not null,prediction_origin_id text,role text not null,score double precision,payload jsonb not null,unique(origin_node,origin_id));
create table if not exists decision_negative_results(id bigint generated by default as identity primary key,origin_node text not null,origin_id text not null,created_at timestamptz not null,hypothesis text not null,reason text,payload jsonb not null,unique(origin_node,origin_id));
create table if not exists decision_audit_bundles(id bigint generated by default as identity primary key,origin_node text not null,origin_id text not null,created_at timestamptz not null,bundle_hash text not null,payload jsonb not null,unique(origin_node,origin_id),unique(bundle_hash));
create table if not exists universe_membership_pit(id bigint generated by default as identity primary key,asset text not null,universe text not null,valid_from timestamptz not null,valid_to timestamptz,known_at timestamptz not null,source text not null,unique(asset,universe,valid_from,known_at));
create table if not exists decision_expectations(id bigint generated by default as identity primary key,origin_node text not null,origin_id text not null,subject text not null,expected double precision,dispersion double precision,known_at timestamptz not null,source text not null,unique(origin_node,origin_id));
create table if not exists causal_edges_pit(id bigint generated by default as identity primary key,origin_node text not null,origin_id text not null,source_node text not null,target_node text not null,confidence double precision,first_known_at timestamptz not null,provenance text not null,falsification jsonb not null default '[]'::jsonb,unique(origin_node,origin_id));
alter table decision_thesis_events enable row level security;
alter table decision_forward_ledger enable row level security;
alter table decision_research_ledger enable row level security;
alter table decision_committee_votes enable row level security;
alter table decision_negative_results enable row level security;
alter table decision_audit_bundles enable row level security;
alter table universe_membership_pit enable row level security;
alter table decision_expectations enable row level security;
alter table causal_edges_pit enable row level security;
comment on table decision_forward_ledger is 'Immutable forward prediction ledger; outcomes append only after maturity. REAL TRADING remains off.';
